import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"Prices and costs","description":"","frontmatter":{"order":3,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/en/02.anleitungen/03.preise-und-kosten.md"},"headers":[],"relativePath":"adapter/sourceanalytix/anleitungen/preise-und-kosten.md","filePath":"adapter/sourceanalytix/anleitungen/preise-und-kosten.md","lastUpdated":null}'),r={name:"adapter/sourceanalytix/anleitungen/preise-und-kosten.md"};function n(s,e,c,u,d,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="prices-and-costs" tabindex="-1">Prices and costs <a class="header-anchor" href="#prices-and-costs" aria-label="Permalink to &quot;Prices and costs&quot;">​</a></h1><p><a id="costs-recalculated-change-price-change"></a></p><h2 id="are-calculated-costs-recalculated-when-i-change-the-price-and-how-do-i-change-it-from-a-certain-date" tabindex="-1">Are calculated costs recalculated when I change the price, and how do I change it from a certain date? <a class="header-anchor" href="#are-calculated-costs-recalculated-when-i-change-the-price-and-how-do-i-change-it-from-a-certain-date" aria-label="Permalink to &quot;Are calculated costs recalculated when I change the price, and how do I change it from a certain date?&quot;">​</a></h2><p>Not on their own. A new price applies from the date under &quot;Valid from&quot;, and costs already booked stay. To recalculate them, use &quot;Recalculate costs from date&quot; on the source.</p><ol><li>On the &quot;Price definitions&quot; tab, enter the new &quot;Price per unit&quot; or &quot;Price per month&quot;.</li><li>Set &quot;Valid from&quot; to the day it applies from. The date may be in the future.</li><li>Save. From 0:00 on that day, SourceAnalytix calculates with the new price.</li></ol><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Give every price change a new &quot;Valid from&quot;. With the old date, the new price replaces the old one retroactively. The dialog flags this with &quot;Price changed but &quot;Valid from&quot; did not …&quot; but still lets you save, so you can fix typos.</p></div><p>If you only change one of the two prices, the other one&#39;s history stays untouched. If you switch supplier, enter the new price in the same price definition, so the price history stays together.</p><p>If a price already applied earlier, set the correct &quot;Valid from&quot;, save, and choose &quot;Recalculate costs from date&quot; with that date on every affected source.</p><p><strong>See also:</strong> <a href="./../referenz/einstellungen#price-definition-structured-categories-base">How is a price definition structured?</a> · <a href="./../referenz/states-und-meldungen#prices-read-written-as-states">Prices as states</a></p><p><a id="include-monthly-base-fee"></a></p><h2 id="how-do-i-include-a-monthly-basic-fee" tabindex="-1">How do I include a monthly basic fee? <a class="header-anchor" href="#how-do-i-include-a-monthly-basic-fee" aria-label="Permalink to &quot;How do I include a monthly basic fee?&quot;">​</a></h2><p>Enter the amount under &quot;Price per month&quot; in the price definition and turn on &quot;Include basic fee&quot; on the source. Divide a yearly basic fee by 12.</p><p>SourceAnalytix books the full monthly amount on the first of each month. On 15 March, with a basic fee of €12 since January, day and week therefore contain €0, the month €12, and quarter and year €36 each.</p><p>You tick the box in the wizard&#39;s &quot;Price&quot; step or later in the detail view under &quot;Settings&quot;.</p><h3 id="several-sources-with-the-same-price-definition" tabindex="-1">Several sources with the same price definition <a class="header-anchor" href="#several-sources-with-the-same-price-definition" aria-label="Permalink to &quot;Several sources with the same price definition&quot;">​</a></h3><p>Every source with &quot;Include basic fee&quot; books the full amount. If several sources belong to one connection, say the house supply and a sub-meter, turn it on for only one of them. Otherwise the &quot;Problems&quot; tab reports &quot;Basic fee is booked twice&quot; with &quot;Switch off here&quot;.</p><p><strong>See also:</strong> <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#costs-stay-0-not-calculated">Costs stay 0</a></p><p><a id="use-dynamic-electricity-price-tibber"></a></p><h2 id="how-do-i-use-a-dynamic-electricity-price-tibber-awattar" tabindex="-1">How do I use a dynamic electricity price (Tibber, Awattar)? <a class="header-anchor" href="#how-do-i-use-a-dynamic-electricity-price-tibber-awattar" aria-label="Permalink to &quot;How do I use a dynamic electricity price (Tibber, Awattar)?&quot;">​</a></h2><p>In the price definition, set the &quot;Price source&quot; to &quot;Datapoint&quot; and choose the current price under &quot;Price state&quot;. SourceAnalytix values all consumption at the price that applied at that time.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>The datapoint must deliver the price per unit of the price definition, for example <code>0.28</code> for 28 cents per kWh. If your adapter delivers cents, convert it first, for example with an alias.</p></div><p>If the price changes between two values of the source, SourceAnalytix splits the consumption by time. The more often the source sends, the more accurate it is. The running costs are kept in <code>sourceanalytix.0.&lt;device&gt;.dynamicCostMemory</code> and survive a restart. If the datapoint has no valid value, SourceAnalytix continues with the last fixed price entered.</p><p>&quot;Recalculate costs from date&quot; spreads the consumption evenly over the period and is only an approximation with hourly prices. The dialog points this out. Only use the action here to fix an error.</p><p><strong>See also:</strong> <a href="./../referenz/states-und-meldungen#prices-read-written-as-states">Prices as states</a> · <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#values-costs-far-too-high">Costs far too high</a></p><p><a id="bill-day-night-tariff"></a></p><h2 id="how-do-i-bill-a-day-night-tariff-high-low-rate" tabindex="-1">How do I bill a day/night tariff (high/low rate)? <a class="header-anchor" href="#how-do-i-bill-a-day-night-tariff-high-low-rate" aria-label="Permalink to &quot;How do I bill a day/night tariff (high/low rate)?&quot;">​</a></h2><p>Set the &quot;Price source&quot; to &quot;Tariff selector&quot;. A datapoint then switches between two prices. Consumption is valued at whichever price applies, but it is not split into high and low rate.</p><ol><li>Provide a datapoint that is, for example, <code>true</code> during one tariff, say via a script or schedule.</li><li>Enter the price for &quot;not active&quot; under &quot;Price per unit&quot; and the price for &quot;active&quot; under &quot;Active tariff price&quot;.</li><li>Choose the switching datapoint under &quot;Price state&quot; and save.</li></ol><p>If &quot;Active selector value&quot; is filled in, for example <code>NT</code>, only exactly that value counts as active. Otherwise the datapoint is active for <code>true</code>, any number other than 0, or any text except <code>0</code>, <code>false</code>, <code>off</code>, <code>no</code> and <code>closed</code>.</p><p>If your meter has separate readings for high and low rate, create two sources with a fixed price instead. That also gives you the consumption per tariff.</p><p><a id="assign-prices-create-custom-tariffs"></a></p><h2 id="how-do-i-assign-prices-and-create-my-own-tariffs-e-g-heat-pump" tabindex="-1">How do I assign prices and create my own tariffs (e.g. heat pump)? <a class="header-anchor" href="#how-do-i-assign-prices-and-create-my-own-tariffs-e-g-heat-pump" aria-label="Permalink to &quot;How do I assign prices and create my own tariffs (e.g. heat pump)?&quot;">​</a></h2><p>Each source has exactly one price definition. For a tariff of your own, such as the heat pump, add another row on the &quot;Price definitions&quot; tab and choose it for the source.</p><ol><li>Add a row on the &quot;Price definitions&quot; tab.</li><li>Enter a unique &quot;Category&quot;, for example <code>HeatPump</code>. The page marks empty or duplicate names with &quot;Category empty or used twice&quot;.</li><li>Choose &quot;Cost Type&quot;, &quot;Unit&quot; and &quot;Price source&quot;, enter the price and save.</li><li>Choose the tariff in the wizard&#39;s &quot;Price&quot; step or in the source&#39;s detail view under &quot;Price definition&quot;.</li></ol><p>The price applies per unit of the price definition. For costs per kilometre choose <code>km</code>, for a price per item <code>piece</code>.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Don&#39;t rename a category while sources use it. Those sources then stop calculating, and the &quot;Problems&quot; tab reports &quot;Price definition no longer exists&quot;. Afterwards, choose the new price definition on every source.</p></div><p><strong>See also:</strong> <a href="./../referenz/einstellungen#price-definition-structured-categories-base">How is a price definition structured?</a> · <a href="./quellen-und-einheiten#unit-datapoint-kwh-wh-m3">Which unit on the datapoint?</a></p>',37)])])}const f=t(r,[["render",n]]);export{p as __pageData,f as default};
